+
+type Send = (res:ServerResponse,status:number,data:unknown)=>void;
+type Body = <T>(req:IncomingMessage)=>Promise<T>;
+
+export function createGitApi(store:GitTaskStore,readBody:Body,send:Send) {
+  const bridge = createGitBridge(store);
+  return async (req:IncomingMessage,res:ServerResponse,url:URL):Promise<boolean> => {
+    const route = url.pathname;
+    if (!(route === '/api/board' || route.startsWith('/api/board/') || route === '/api/tools' || route === '/api/tasks' || route.startsWith('/api/tasks/'))) return false;
+    try {
+      let result:unknown;
+      let status=200;
+      const match=route.match(/^\/api\/tasks\/(TASK-\d{3,})(?:\/(history|status))?$/);
+      if (req.method === 'GET' && route === '/api/board') result={mode:'git',sourceRef:'main',transitions};
+      else if (req.method === 'GET' && route === '/api/board/contracts') result=await store.contracts();
+      else if (req.method === 'GET' && route === '/api/tools') result=bridge.getDefinedTools().map(t=>({name:t.name,description:t.description,inputSchema:t.inputSchema}));
+      else if (req.method === 'GET' && route === '/api/tasks') result=await store.list(url.searchParams.get('status') ?? undefined);
+      else if (req.method === 'POST' && route === '/api/tasks') {
+        result=await store.create(creationSchema.parse(await readBody(req))); status=201;
+      } else if (req.method === 'GET' && match && !match[2]) result=await store.get(match[1]);
+      else if (req.method === 'GET' && match?.[2] === 'history') result=await store.history(match[1]);
+      else if (req.method === 'PATCH' && match?.[2] === 'status') result=await store.transition(match[1],transitionSchema.parse(await readBody(req)));
+      else throw new BoardGitError('This operation is unavailable for Git tasks; use a canonical state transition',409);
+      send(res,status,result);
+    } catch (error:any) {
+      const status=error instanceof BoardGitError ? error.status : error.name === 'ZodError' || error instanceof SyntaxError ? 400 : 503;
+      send(res,status,{error:error.message || 'Git coordinator unavailable'});
+    }
+    return true;
+  };
